script:
test("end date is included, visit is covered, and one visit remains", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-04-30"
  }), { covered: true, remaining: 1 });
});

test("one day after the end date is not covered and leaves two visits", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-05-01"
  }), { covered: false, remaining: 2 });
});

test("used equals approved inside the window is not covered and leaves zero", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 6,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-03-16"
  }), { covered: false, remaining: 0 });
});

test("start date is included, visit is covered, and one visit remains", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-02-01"
  }), { covered: true, remaining: 1 });
});

test("one day before the start date is not covered and leaves two visits", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-01-31"
  }), { covered: false, remaining: 2 });
});

test("one day after the start date is covered and leaves one visit", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-02-02"
  }), { covered: true, remaining: 1 });
});

test("one day before the end date is covered and leaves one visit", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-04-29"
  }), { covered: true, remaining: 1 });
});

test("used one below approved covers the visit and leaves zero", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 3,
    usedVisits: 2,
    startDate: "2026-07-01",
    endDate: "2026-07-31",
    visitDate: "2026-07-15"
  }), { covered: true, remaining: 0 });
});

test("zero approved and zero used is not covered and leaves zero", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 0,
    usedVisits: 0,
    startDate: "2026-08-01",
    endDate: "2026-08-31",
    visitDate: "2026-08-15"
  }), { covered: false, remaining: 0 });
});

test("one approved and none used on the last day of January is covered and leaves zero", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 1,
    usedVisits: 0,
    startDate: "2026-01-01",
    endDate: "2026-01-31",
    visitDate: "2026-01-31"
  }), { covered: true, remaining: 0 });
});

test("January 1 inside a December to January span is covered and leaves two", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 4,
    usedVisits: 1,
    startDate: "2025-12-31",
    endDate: "2026-01-31",
    visitDate: "2026-01-01"
  }), { covered: true, remaining: 2 });
});

test("December 31 as the start date is covered and leaves two", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 4,
    usedVisits: 1,
    startDate: "2025-12-31",
    endDate: "2026-01-31",
    visitDate: "2025-12-31"
  }), { covered: true, remaining: 2 });
});

test("leap day as the end date is covered and leaves four", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 7,
    usedVisits: 2,
    startDate: "2024-02-01",
    endDate: "2024-02-29",
    visitDate: "2024-02-29"
  }), { covered: true, remaining: 4 });
});

test("one day after a leap day end is not covered and leaves five", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 7,
    usedVisits: 2,
    startDate: "2024-02-01",
    endDate: "2024-02-29",
    visitDate: "2024-03-01"
  }), { covered: false, remaining: 5 });
});

test("first of a middle month with a month-end start is covered and leaves six", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 9,
    usedVisits: 2,
    startDate: "2026-01-31",
    endDate: "2026-06-30",
    visitDate: "2026-03-01"
  }), { covered: true, remaining: 6 });
});

test("an unknown extra field throws unknown field extra", function () {
  assert.throws(function () {
    code.checkAuthorization({
      approvedVisits: 6,
      usedVisits: 4,
      startDate: "2026-02-01",
      endDate: "2026-04-30",
      visitDate: "2026-03-16",
      extra: 1
    });
  }, /unknown field: extra/);
});
